"""기준 집합(잠금 → 대상 환경 마커로 고른 runtime)과 스캔 결과의 대조."""

import pytest

import license_audit as la
from kb_testing.audit_fixtures import env, run_audit, scan_item

PRODUCT_RUNTIME = """\
# This file was autogenerated by uv via the following command:
#    uv export --locked --all-packages --no-dev --no-emit-workspace --no-hashes
pydantic==2.12.0
    # via kookabug-core
typing-extensions==4.15.0
    # via pydantic
"""
PRODUCT_SCAN = [
    scan_item("pydantic", "2.12.0", "MIT"),
    scan_item("typing_extensions", "4.15.0", "PSF-2.0"),
]


def test_product_only_package_audited() -> None:
    result = run_audit(PRODUCT_RUNTIME, PRODUCT_SCAN)
    assert result.ok, result.problems
    assert {r[0] for r in result.python_rows} == {"pydantic", "typing-extensions"}
    assert "pydantic 2.12.0" in result.notices

    # 제품 패키지의 라이선스가 나쁘면 실패한다 (판정 대상에 실제로 들어간다)
    bad = [scan_item("pydantic", "2.12.0", "GPL-3.0"), PRODUCT_SCAN[1]]
    assert not run_audit(PRODUCT_RUNTIME, bad).ok


def test_dev_only_package_not_in_runtime_set_and_not_in_notices() -> None:
    # dev 그룹(pytest 등)은 `uv export --no-dev`에 없다. 대상 venv에도 설치되지 않는다
    result = run_audit(PRODUCT_RUNTIME, PRODUCT_SCAN)
    assert result.ok
    assert "pytest" not in result.notices
    assert all(r[0] != "pytest" for r in result.python_rows)

    # 대상 venv에 dev 패키지가 섞이면 오염으로 실패한다
    polluted = run_audit(PRODUCT_RUNTIME, [*PRODUCT_SCAN, scan_item("pytest", "8.4.0")])
    assert not polluted.ok
    assert any("[오염] pytest" in p for p in polluted.problems)


@pytest.mark.parametrize("shared", ["prettytable", "wcwidth"])
def test_dependency_shared_with_audit_tool_kept_in_audit_and_notices(shared: str) -> None:
    # 제품도 감사 도구(pip-licenses)도 쓰는 패키지는 기준 집합에 있으므로 판정·NOTICES에 남는다
    runtime = PRODUCT_RUNTIME + f"{shared}==3.0.0\n"
    scan = [*PRODUCT_SCAN, scan_item(shared, "3.0.0", "BSD License", f"{shared.upper()} TEXT")]
    result = run_audit(runtime, scan)
    assert result.ok, result.problems
    assert f"{shared} 3.0.0" in result.notices
    assert f"{shared.upper()} TEXT" in result.notices
    assert any(shared in n and "제품 의존성" in n for n in result.notes)

    # 같은 패키지가 제품 의존성이 아닌데 대상 환경에 있으면 도구 오염으로 실패한다
    polluted = run_audit(PRODUCT_RUNTIME, scan)
    assert not polluted.ok
    assert any(shared in p and "감사 도구" in p for p in polluted.problems)


def test_runtime_package_missing_from_scan_fails() -> None:
    result = run_audit(PRODUCT_RUNTIME, PRODUCT_SCAN[:1])
    assert not result.ok
    assert any("[누락] typing-extensions" in p for p in result.problems)
    # 누락돼도 NOTICES에는 기준 집합 전체가 자리로 남는다
    assert "typing-extensions 4.15.0" in result.notices


def test_extra_package_in_scan_fails() -> None:
    result = run_audit(PRODUCT_RUNTIME, [*PRODUCT_SCAN, scan_item("pip-licenses", "5.5.5")])
    assert not result.ok
    assert any("[오염] pip-licenses" in p for p in result.problems)
    assert "pip-licenses" not in result.notices


def test_version_mismatch_between_lock_and_scan_fails() -> None:
    scan = [scan_item("pydantic", "2.11.0", "MIT"), PRODUCT_SCAN[1]]
    result = run_audit(PRODUCT_RUNTIME, scan)
    assert not result.ok
    assert any("[버전 불일치] pydantic" in p for p in result.problems)


def test_version_compare_is_normalized() -> None:
    runtime = "foo==1.0\n"
    assert run_audit(runtime, [scan_item("foo", "1.0.0")]).ok


# ---------------------------------------------------------------- 마커 환경

VERSION_BRANCH = """\
sampledep==1.0 ; python_full_version < '3.14'
sampledep==2.0 ; python_full_version >= '3.14'
"""


def test_version_branch_uses_target_python_marker() -> None:
    # 대상 3.14: 2.0만 활성
    assert run_audit(VERSION_BRANCH, [scan_item("sampledep", "2.0")]).ok
    mismatch = run_audit(VERSION_BRANCH, [scan_item("sampledep", "1.0")])
    assert any("[버전 불일치] sampledep" in p for p in mismatch.problems)

    # 대상 3.12: 감사 도구가 어느 Python에서 돌든 대상 환경 값으로 고른다
    py312 = env(python_version="3.12", python_full_version="3.12.11")
    assert run_audit(VERSION_BRANCH, [scan_item("sampledep", "1.0")], marker_env=py312).ok
    assert not run_audit(VERSION_BRANCH, [scan_item("sampledep", "2.0")], marker_env=py312).ok


def test_non_windows_only_dependency_not_required_on_windows() -> None:
    runtime = PRODUCT_RUNTIME + "unixdep==1.0 ; sys_platform != 'win32'\n"
    result = run_audit(runtime, PRODUCT_SCAN)
    assert result.ok, result.problems
    assert "unixdep" not in result.notices
    assert any("unixdep" in n and "비활성" in n for n in result.notes)

    # 리눅스 대상이면 활성이라 없으면 실패한다
    linux = env(sys_platform="linux", os_name="posix", platform_system="Linux")
    assert not run_audit(runtime, PRODUCT_SCAN, marker_env=linux).ok


def test_active_marker_dependency_missing_still_fails() -> None:
    runtime = PRODUCT_RUNTIME + "colorama==0.4.6 ; sys_platform == 'win32'\n"
    result = run_audit(runtime, PRODUCT_SCAN)
    assert not result.ok
    assert any("[누락] colorama" in p for p in result.problems)

    ok = run_audit(runtime, [*PRODUCT_SCAN, scan_item("colorama", "0.4.6", "BSD License")])
    assert ok.ok, ok.problems


def test_two_active_versions_is_input_error() -> None:
    runtime = "dup==1.0\ndup==2.0 ; sys_platform == 'win32'\n"
    with pytest.raises(la.AuditInputError):
        run_audit(runtime, [scan_item("dup", "1.0")])


def test_marker_env_must_be_complete() -> None:
    with pytest.raises(la.AuditInputError):
        la.load_marker_env({"sys_platform": "win32"})


@pytest.mark.parametrize("line", ["foo>=1.0", "foo", "-e ./python/kookabug_sdk"])
def test_runtime_requirements_must_be_pinned(line: str) -> None:
    with pytest.raises(la.AuditInputError):
        la.parse_runtime(line + "\n")
